    fill: h.fill,
    bn: h.amountBn,
  }));
}

export function riskScatter(region: "all" | "US" | "Europe" | "APAC" | "Other") {
  return RISK_SCATTER.filter((p) => region === "all" || p.region === region);
}

export function meterBars() {
  return METER_COMPARE.map((m) => ({
    name: m.short,
    full: m.label,
    value: m.top1SharePct,
    fill: m.fill,
    tip: m.top1Label,
  }));
}

