    name: c.short,
    full: c.label,
    value:
      metric === "us"
        ? c.shareOfUsProjectPct
        : metric === "global"
          ? c.shareOfGlobalProjectPct
          : metric === "growth"
            ? c.growthYoYPct
            : c.riskScore,
    fill: c.fill,
    bn: c.projectBn,
  }));
}

