  return FACILITY_REGIONS.map((r) => ({
    name: r.short,
    full: r.region,
    value: metric === "share" ? r.sharePct : r.amountBn,
    fill: r.fill,
    risk: r.powerRisk,
  }));
}

export function corridorBars(metric: "us" | "global" | "growth" | "risk") {
  return US_CORRIDORS.map((c) => ({
    name: c.short,
    full: c.label,
    value:
      metric === "us"
        ? c.shareOfUsProjectPct
        : metric === "global"
          ? c.shareOfGlobalProjectPct
          : metric === "growth"
            ? c.growthYoYPct
            : c.riskScore,
    fill: c.fill,
    bn: c.projectBn,
  }));
}

