];

export type RiskScatterPoint = {
  id: string;
  label: string;
  region: "US" | "Europe" | "APAC" | "Other";
  creditBn: number;
  riskScore: number;
  growthYoYPct: number;
  fill: string;
};

export const RISK_SCATTER: RiskScatterPoint[] = [
  {
    id: "nova",
